/* @autogenerated */
package net.civeira.phylax.feature.observe.anomaly;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

import net.civeira.phylax.feature.observe.metric.Histogram;
import net.civeira.phylax.feature.observe.metric.MetricDeriver;
import net.civeira.phylax.feature.observe.metric.MetricPoint;

/**
 * Compares the last minutes of each source with what is usual for that slot of the week
 * ({@link Baselines}): an anomaly is a value more than {@code sigma} deviations away from the mean,
 * with a minimum of traffic (one request is never an anomaly). The traffic is checked in both
 * directions; the error rate and the latency only when they go up.
 */
public final class AnomalyDetector {

  /** A metric of a source out of its usual values. */
  public record Anomaly(String source, String metric, double value, double mean, double std,
      String direction) {}

  private final double sigma;
  private final long minRequests;

  public AnomalyDetector(final double sigma, final long minRequests) {
    this.sigma = sigma <= 0 ? 3 : sigma;
    this.minRequests = Math.max(1, minRequests);
  }

  /**
   * @param recent minute points of the last {@code minutes} (any source)
   */
  public List<Anomaly> detect(final Baselines baselines, final List<MetricPoint> recent,
      final int minutes, final long now) {
    Map<String, double[]> totals = new HashMap<>();
    Map<String, Histogram> latency = new HashMap<>();
    for (MetricPoint point : recent) {
      if (MetricDeriver.special(point.method())) {
        continue;
      }
      double[] acc = totals.computeIfAbsent(point.src(), s -> new double[2]);
      acc[0] += point.count();
      acc[1] += point.errors();
      latency.computeIfAbsent(point.src(), s -> new Histogram()).merge(point.buckets());
    }
    int slot = Baselines.slot(now);
    List<Anomaly> result = new ArrayList<>();
    for (Map.Entry<String, double[]> entry : totals.entrySet()) {
      String source = entry.getKey();
      double count = entry.getValue()[0];
      if (count < minRequests) {
        continue;
      }
      check(result, baselines, source, slot, Baselines.RPM, count / Math.max(1, minutes),
          Set.of("up", "down"));
      check(result, baselines, source, slot, Baselines.ERRORS, 100.0 * entry.getValue()[1] / count,
          Set.of("up"));
      Double p95 = latency.get(source).percentile(0.95);
      if (null != p95) {
        check(result, baselines, source, slot, Baselines.P95, p95, Set.of("up"));
      }
    }
    return result;
  }

  private void check(final List<Anomaly> result, final Baselines baselines, final String source,
      final int slot, final String metric, final double value, final Set<String> directions) {
    Baselines.Stat stat = baselines.stat(source, slot, metric);
    if (null == stat || stat.samples() < 3) {
      return;
    }
    // A floor for the deviation: a perfectly flat history must not turn any change into an anomaly
    double std = Math.max(stat.std(), Math.max(0.5, Math.abs(stat.mean()) * 0.1));
    double z = (value - stat.mean()) / std;
    String direction = z > 0 ? "up" : "down";
    if (Math.abs(z) > sigma && directions.contains(direction)
        && !(Baselines.ERRORS.equals(metric) && value < 1)) {
      result.add(new Anomaly(source, metric, Math.round(value * 10) / 10.0,
          Math.round(stat.mean() * 10) / 10.0, Math.round(std * 10) / 10.0, direction));
    }
  }
}
